solution.main.cpp:
#include <iostream>

int main()
{
    int score{ 10 };
    std::cout << score << '\n';

    score = 25;
    std::cout << score << '\n';

    score = score + 5;
    std::cout << score << '\n';

    score = score * 2;
    std::cout << score << '\n';

    return 0;
}
